parameters.jsCode:
// Input processing: normalise whatever the website sent into clean, safe fields.
// Never throws - thin input is handled by the agent as a clarifying question.
const b = ($input.first().json.body) || {};
const clean = (v) => (typeof v === 'string' ? v.trim() : '');

let items = [];
if (Array.isArray(b.items)) {
  items = b.items.map(clean).filter(Boolean);
} else if (clean(b.items)) {
  items = clean(b.items).split(',').map((s) => s.trim()).filter(Boolean);
}

return [{
  json: {
    destination: clean(b.destination) || 'not provided',
    purpose: clean(b.purpose) || 'not provided',
    items: items,
    items_text: items.length ? items.join(', ') : 'none listed',
    special_conditions: clean(b.special_conditions) || 'none mentioned',
    use_weather: b.use_weather === true,
    location: clean(b.location) || '',
    received_at: new Date().toISOString()
  }
}];

